package com.iridium126.createmanaindustry.content.allaystorm;
import org.junit.jupiter.api.Test;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class StormFeedbackPacketTest {
 @Test void completedCodecCarries12288AndRejectsOversizedPayload(){var b=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),net.minecraft.core.RegistryAccess.EMPTY,net.neoforged.neoforge.network.connection.ConnectionType.OTHER);try{var bits=new BitSet();for(int rank:new int[]{0,63,4095,4096,8191,12287})bits.set(rank);var p=new com.iridium126.createmanaindustry.content.allaystorm.network.StormAttackCompletedPacket(net.minecraft.world.level.Level.OVERWORLD.location(),12,9,bits.toLongArray());var codec=com.iridium126.createmanaindustry.content.allaystorm.network.StormAttackCompletedPacket.STREAM_CODEC;codec.encode(b,p);var q=codec.decode(b);assertEquals(p.dimension(),q.dimension());assertEquals(p.epoch(),q.epoch());assertEquals(p.id(),q.id());assertArrayEquals(p.ranks(),q.ranks());assertFalse(b.isReadable());b.clear();codec.encode(b,new com.iridium126.createmanaindustry.content.allaystorm.network.StormAttackCompletedPacket(p.dimension(),12,9,new long[193]));assertThrows(Exception.class,()->codec.decode(b));}finally{b.release();}}
 @Test void gatherCodecPreservesIdentity(){var b=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),net.minecraft.core.RegistryAccess.EMPTY,net.neoforged.neoforge.network.connection.ConnectionType.OTHER);try{var p=new com.iridium126.createmanaindustry.content.allaystorm.network.StormAttackGatheredPacket(net.minecraft.world.level.Level.NETHER.location(),123,42,new long[]{-1},new long[]{-1});var codec=com.iridium126.createmanaindustry.content.allaystorm.network.StormAttackGatheredPacket.STREAM_CODEC;codec.encode(b,p);var q=codec.decode(b);assertEquals(p.dimension(),q.dimension());assertEquals(p.id(),q.id());assertEquals(p.epoch(),q.epoch());assertArrayEquals(p.ready(),q.ready());assertArrayEquals(p.eligible(),q.eligible());assertFalse(b.isReadable());}finally{b.release();}}
}
